# Compare orthogonal rectangle approximations over varied affine grids.
import numpy as np
import astropy.units as u
from astropy.coordinates import SkyCoord
from astropy.wcs import WCS
from photutils.aperture import RectangularAperture
from photutils.utils._wcs_helpers import _sky_to_pixel_setup,_ellipse_from_matrix
rng=np.random.default_rng(443201);center=SkyCoord(211.3*u.deg,-12.7*u.deg);shape=(221,223);yy,xx=np.mgrid[:shape[0],:shape[1]];grids=[]
for i in range(12):
 sx,sy=rng.uniform(.10,.21,2);rot=rng.uniform(-np.pi,np.pi);shear=rng.uniform(-.4,.4);c,s=np.cos(rot),np.sin(rot);m=np.array([[c,-s],[s,c]])@np.array([[1,shear],[0,1]])@np.diag([sx,sy]);m[1]*=(-1 if i%2 else 1)
 w=WCS(naxis=2);w.wcs.crpix=[112.,111.];w.wcs.crval=[center.ra.deg,center.dec.deg];w.wcs.cd=m/3600;w.wcs.ctype=['RA---TAN','DEC--TAN'];world=w.pixel_to_world(xx,yy);sep=center.separation(world).arcsec;pa=center.position_angle(world).rad;grids.append((w,sep*np.sin(pa),sep*np.cos(pa)))
for width,height,deg in [(6.2,1.3,21.),(4.,4.,73.),(7.,2.5,146.),(1.3,6.2,21.)]:
 th=np.deg2rad(deg);ms=np.array([[.5*width*np.sin(th),.5*height*np.cos(th)],[.5*width*np.cos(th),-.5*height*np.sin(th)]]);out={x:[] for x in ('svd','edge_area')}
 for w,xi,eta in grids:
  along=xi*np.sin(th)+eta*np.cos(th);across=xi*np.cos(th)-eta*np.sin(th);data=500*np.exp(-.5*((along/2.8)**2+(across/.9)**2))+4;c,j=_sky_to_pixel_setup(center,w);mp=j@ms;pw,ph,pa=_ellipse_from_matrix(mp);uw=mp[:,0];ang=np.arctan2(uw[1],uw[0]);ew=2*np.linalg.norm(uw);eh=width*height*abs(np.linalg.det(j))/ew
  aps={'svd':RectangularAperture(c,pw,ph,theta=pa),'edge_area':RectangularAperture(c,ew,eh,theta=ang)}
  for k,a in aps.items():out[k].append(a.do_photometry(data,method='subpixel',subpixels=9)[0][0]/a.area)
 print((width,height,deg),{k:(max(v)-min(v))/np.median(v) for k,v in out.items()})
